15	  return (
16	    <>
17	      <JsonLd
18	        data={{
19	          "@context": "https://schema.org",
20	          "@type": "Organization",
21	          name: "Nxeon",
22	          url: APP_URL,
23	          // A raster logo (min 112x112) is what Google uses for the brand/knowledge
24	          // panel — an SVG favicon is not eligible. /logo.png is the same mark the
