9	export default async function sitemap(): Promise<MetadataRoute.Sitemap> {
10	  const now = new Date();
11	
12	  const staticRoutes: Array<{ path: string; priority: number; freq: MetadataRoute.Sitemap[number]["changeFrequency"] }> = [
13	    { path: "", priority: 1.0, freq: "weekly" },
14	    { path: "/features", priority: 0.8, freq: "monthly" },
15	    { path: "/vibe-coding", priority: 0.8, freq: "monthly" },
16	    { path: "/matrix", priority: 0.9, freq: "monthly" },
17	    { path: "/pricing", priority: 0.9, freq: "weekly" },
18	    { path: "/vps", priority: 0.8, freq: "monthly" },
19	    { path: "/domains", priority: 0.8, freq: "monthly" },
20	    { path: "/compare", priority: 0.7, freq: "monthly" },
21	    { path: "/vps-vs-digitalocean", priority: 0.7, freq: "monthly" },
22	    { path: "/vps-vs-hostinger", priority: 0.7, freq: "monthly" },
23	    { path: "/about", priority: 0.5, freq: "monthly" },
24	    { path: "/contact", priority: 0.5, freq: "monthly" },
25	    { path: "/blog", priority: 0.7, freq: "weekly" },
26	    { path: "/tools", priority: 0.7, freq: "weekly" },
27	    ...TOOL_SLUGS.map((slug) => ({
28	      path: `/tools/${slug}`,
29	      priority: 0.6,
30	      freq: "monthly" as const,
31	    })),
32	    { path: "/status", priority: 0.4, freq: "daily" },
33	    { path: "/legal/terms", priority: 0.3, freq: "yearly" },
34	    { path: "/legal/privacy", priority: 0.3, freq: "yearly" },
35	    { path: "/legal/aup", priority: 0.3, freq: "yearly" },
36	    { path: "/legal/sla", priority: 0.3, freq: "yearly" },
37	  ];
38	
39	  const entries: MetadataRoute.Sitemap = staticRoutes.map((r) => ({
40	    url: `${APP_URL}${r.path}`,
41	    lastModified: now,
42	    changeFrequency: r.freq,
43	    priority: r.priority,
44	  }));
45	
46	  // Published blog posts (model may not be migrated yet — access defensively).
47	  try {
48	    const blogModel = (db as unknown as { blogPost?: { findMany: (a: unknown) => Promise<Array<{ slug: string; updatedAt: Date }>> } }).blogPost;
49	    const posts = blogModel
50	      ? await blogModel.findMany({
51	          where: { published: true },
52	          select: { slug: true, updatedAt: true },
53	          orderBy: { publishedAt: "desc" },
54	        })
55	      : [];
56	    for (const p of posts) {
57	      entries.push({
58	        url: `${APP_URL}/blog/${p.slug}`,
59	        lastModified: p.updatedAt,
60	        changeFrequency: "monthly",
61	        priority: 0.6,
62	      });
63	    }
64	  } catch {
65	    // blogPost model not migrated yet — skip.
66	  }
67	
68	  return entries;
69	}
