72	export function MarketingHeader() {
73	  const pathname = usePathname();
74	  const [open, setOpen] = useState(false); // mobile drawer
75	  const [menu, setMenu] = useState<null | "products" | "company">(null); // desktop dropdown
76	  const [scrolled, setScrolled] = useState(false);
77	  const [authed, setAuthed] = useState(false);
78	  const closeTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
79	
80	  // Show "Back to portal" for a signed-in visitor while keeping marketing pages
81	  // static. Two-step, after mount: (1) optimistic read of the non-httpOnly
82	  // `nxeon_authed` flag cookie (instant, no flash when present), then (2) an
83	  // authoritative probe to /api/auth/status which reads the real session cookie
84	  // server-side — so it's correct even if the flag cookie is missing or stale.
85	  useEffect(() => {
86	    setAuthed(document.cookie.split("; ").some((c) => c.startsWith("nxeon_authed=")));
87	    let alive = true;
88	    fetch("/api/auth/status", { cache: "no-store" })
89	      .then((r) => (r.ok ? r.json() : null))
90	      .then((d) => {
91	        if (alive && d && typeof d.authed === "boolean") setAuthed(d.authed);
92	      })
93	      .catch(() => {});
94	    return () => {
95	      alive = false;
96	    };
97	  }, []);
98	
99	  useEffect(() => {
100	    const onScroll = () => setScrolled(window.scrollY > 8);
101	    onScroll();
102	    window.addEventListener("scroll", onScroll, { passive: true });
103	    return () => window.removeEventListener("scroll", onScroll);
104	  }, []);
105	
106	  useEffect(() => {
107	    setOpen(false);
108	    setMenu(null);
109	  }, [pathname]);
